head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > preventAddRowOnPaste]<br/>줄바꿈 구분자가 포함된 데이터를 붙여넣기(Ctrl+V)할 때 새로운 Row 추가를 차단할지 설정합니다.",
    "validation" : [
        "줄바꿈 구분자가 포함된 데이터를 붙여넣기(Ctrl+V)할 때 새로운 Row 추가를 차단할지 설정합니다. checkEditOnPaste=true, copyType='default' 일때만 동작합니다.",
        "true 설정 시 줄바꿈 데이터가 있어도 새로운 Row 가 추가되지 않으며, 새 Row 에 붙을 데이터는 사라집니다.",
        "false(기본값) 설정 시 줄바꿈 데이터가 현재 Row 수를 초과하면 부족한 만큼 Row 가 자동 추가되며, 추가된 Row 는 RowStatus 'C' 상태로 DataList 에 추가됩니다.",
        "Cell 단위로 붙여넣기 되면 onviewchange 이벤트가 Cell 단위로 발생합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 복사 소스 textarea(정적 배치) 에 개행 포함 값(3줄) 설정 → 현재 Row 수(2) 초과 유도
    txa_pasteSource.setValue("A\nB\nC");

    // 안내 및 붙여넣기 전 그리드 상태 출력
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    bottom.setReturnValue("[안내] textarea 3줄 복사(Ctrl+C) 후 col1 셀 클릭(포커스)하고 붙여넣기(Ctrl+V) / preventAddRowOnPaste=" + target1.options.preventAddRowOnPaste);
    scwin.dumpGridState(bottom, "붙여넣기 전");
};



// comp 생성
//  - 편집 가능한 단일 line GridView (gBody 1개 row, 4 Column)
//  - checkEditOnPaste=true, copyType='default' 하드코딩 (preventAddRowOnPaste 가 동작하는 전제)
//  - preventAddRowOnPaste 는 con_preventAddRowOnPaste 선택값(기본 false) 으로 생성
//  - dataList 는 적은 수(2건) 로 구성 → 줄바꿈 3건(A,B,C) 붙여넣기 시 Row 부족 상황 유도
//  - focusMode=both (포커스 Cell 기준 붙여넣기), rowStatusVisible=true (RowStatus 'C' 확인용)
scwin.gVar = { "cPreventAddRowOnPaste" : "false" };

scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="편집 가능 GridView / preventAddRowOnPaste=' + scwin.gVar.cPreventAddRowOnPaste + ' / checkEditOnPaste=true, copyType=default / 초기 데이터 2건"', '', 'label1');

    // 복사 소스 안내 라벨 (textarea 는 grp_parameter 영역에 정적 배치, 값은 onpageload 에서 설정)
    $c.gcm.createLabel('label="↓ 이 텍스트(3줄)를 복사(Ctrl+C)한 뒤 그리드 셀을 클릭(포커스)하고 붙여넣기(Ctrl+V) 하세요"', '', 'label_guide');

    // dataList 생성 (4 Column = col1~col4, 데이터 2건)
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strData += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strData += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strData += '<w2:column id="col4" name="name4" dataType="text"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [];
    for (let i = 1; i <= 2; i++) {
        jsonData.push({
            "col1" : "c1_" + i, "col2" : "c2_" + i,
            "col3" : "c3_" + i, "col4" : "c4_" + i
        });
    }
    dlt_bind.setJSON(jsonData);

    // 조건 설정 (Property : preventAddRowOnPaste, 전제 옵션 하드코딩)
    let properties = {
        preventAddRowOnPaste : scwin.gVar.cPreventAddRowOnPaste,
        checkEditOnPaste     : "true",
        copyType             : "default",
        focusMode            : "both",
        rowStatusVisible     : "true",
        rowStatusHeaderValue : "St."
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩 (onviewchange)
    let eList = $c.gcm.createEList(["onviewchange"]);

    // target 생성 (단일 line, 4 Column 편집 가능 그리드)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" id="" style="width:520px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="preventAddRowOnPaste 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcolumn1" value="name1"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcolumn2" value="name2"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcolumn3" value="name3"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcolumn4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col2" editType="text"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// con_preventAddRowOnPaste 변경 시 Target 재생성 시 사용할 값 갱신용
scwin.con_preventAddRowOnPaste_onchange = function () {
    scwin.gVar.cPreventAddRowOnPaste = con_preventAddRowOnPaste.getText();
}



// onviewchange 이벤트 핸들러 (Cell 단위 발생 확인)
//  - 붙여넣기로 값이 바뀐 Cell 마다 Cell 단위로 발생
//  - 사용자가 직접 붙여넣기(Ctrl+V) 시 발생하며, 발생 직후 현재 그리드 상태(Row 수/RowStatus/col1)를 자동 출력
scwin.target1_onviewchange = function (info) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("[onviewchange] row=" + info.rowIndex + ", col=" + info.colId + ", " + info.oldValue + " → " + info.newValue);
    // 붙여넣기 결과 상태 자동 출력 (preventAddRowOnPaste 동작 확인)
    scwin.dumpGridState(bottom, "붙여넣기 후 (preventAddRowOnPaste=" + target1.options.preventAddRowOnPaste + ")");
}



// 현재 그리드 상태(데이터 Row 수 / 각 Row 의 RowStatus 와 col1~col4 값) 출력 공통 함수
//  - getRowCount : 데이터 Row 수
//  - getRowStatus : 각 Row 상태값 (자동 추가된 Row 는 'C')
//  - col1~col4 값 : 붙여넣은 값(A/B/C) 반영 여부 확인
scwin.dumpGridState = function (bottom, title) {
    let rowCount = target1.getRowCount();
    let rows = [];
    for (let r = 0; r < rowCount; r++) {
        rows.push("[" + r + "] " + target1.getRowStatus(r) + "/" + target1.getCellData(r, "col1") + "," + target1.getCellData(r, "col2") + "," + target1.getCellData(r, "col3") + "," + target1.getCellData(r, "col4"));
    }
    bottom.setReturnValue(title + " : Row수=" + rowCount + " | " + rows.join(", "));
}
